25	func TestParseRuleVersionValidation(t *testing.T) {
26		bad := []struct {
27			name string
28			spec string
29		}{
30			{"not json", `{"id":`},
31			{"trailing garbage", `{"id":"v","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":2}}} extra`},
32			{"missing id", `{"rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`},
33			{"empty id", `{"id":"","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`},
34			{"missing rules", `{"id":"v"}`},
35			{"missing sandwich", `{"id":"v","rules":{"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`},
36			{"missing displacement", `{"id":"v","rules":{"sandwich":{"enabled":true,"severity":3}}}`},
37			{"missing enabled", `{"id":"v","rules":{"sandwich":{"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`},
38			{"missing severity", `{"id":"v","rules":{"sandwich":{"enabled":true},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`},
39			{"missing multiplier", `{"id":"v","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2}}}`},
40			{"severity zero", `{"id":"v","rules":{"sandwich":{"enabled":true,"severity":0},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`},
41			{"severity six", `{"id":"v","rules":{"sandwich":{"enabled":true,"severity":6},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`},
42			{"severity string", `{"id":"v","rules":{"sandwich":{"enabled":true,"severity":"3"},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`},
43			{"severity fractional", `{"id":"v","rules":{"sandwich":{"enabled":true,"severity":2.5},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`},
44			{"enabled string", `{"id":"v","rules":{"sandwich":{"enabled":"yes","severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`},
45			{"multiplier one", `{"id":"v","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":1}}}`},
46			{"multiplier 101", `{"id":"v","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":101}}}`},
47			{"multiplier fractional", `{"id":"v","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":2.5}}}`},
48			{"unknown rule", `{"id":"v","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":2},"frontrun":{"enabled":true,"severity":1}}}`},
49			{"unknown field", `{"id":"v","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":2}},"extra":1}`},
50			{"sandwich with multiplier", `{"id":"v","rules":{"sandwich":{"enabled":true,"severity":3,"multiplier":2},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`},
51		}
52		for _, tc := range bad {
53			t.Run(tc.name, func(t *testing.T) {
54				if _, err := ParseRuleVersion([]byte(tc.spec)); err == nil {
55					t.Fatal("expected error")
56				}
57			})
58		}
59		v, err := ParseRuleVersion([]byte(strictSpec))
60		if err != nil {
61			t.Fatalf("valid spec rejected: %v", err)
62		}
63		if v.ID != "strict" || !v.Rules.Sandwich.Enabled || v.Rules.Sandwich.Severity != 5 ||
64			!v.Rules.Displacement.Enabled || v.Rules.Displacement.Severity != 4 || v.Rules.Displacement.Multiplier != 5 {
65			t.Fatalf("parsed version wrong: %+v", v)
66		}
