69	const validVersionSpec = `{"id":"v","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`
70	
71	func TestParseRuleVersionRejectsNonObjects(t *testing.T) {
72		nonObjects := []struct {
73			name string
74			spec string
75		}{
76			{"empty", ``},
77			{"whitespace only", " \n\t\r"},
78			{"null", `null`},
79			{"array", `[{"id":"v"}]`},
80			{"string", `"v"`},
81			{"number", `42`},
82			{"boolean", `true`},
83		}
84		for _, tc := range nonObjects {
85			t.Run(tc.name, func(t *testing.T) {
86				_, err := ParseRuleVersion([]byte(tc.spec))
87				if err == nil {
88					t.Fatal("non-object spec accepted")
89				}
90				// A non-object is neither a duplicate-field problem nor trailing data.
91				if errors.Is(err, ErrDuplicateField) {
92					t.Fatalf("non-object reported as duplicate field: %v", err)
93				}
94				if errors.Is(err, ErrTrailingData) {
95					t.Fatalf("non-object reported as trailing data: %v", err)
96				}
97			})
98		}
99	}
100	
101	func TestParseRuleVersionAllowsSurroundingWhitespace(t *testing.T) {
102		for _, spec := range []string{
103			validVersionSpec,
