401		builtinSpec := `{"id":"builtin","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`
402		if _, _, err := RegisterVersion(dir, []byte(builtinSpec)); err == nil {
403			t.Fatal("registering over the built-in id must fail")
404		}
405		// Enable persists and is visible to a fresh reader.
406		if _, err := EnableVersion(dir, "strict"); err != nil {
407			t.Fatal(err)
408		}
409		_, enabled, err = ListVersions(dir)
410		if err != nil {
411			t.Fatal(err)
412		}
413		if enabled != "strict" {
414			t.Fatalf("enabled = %q, want strict", enabled)
415		}
