417		if err != nil || got != v {
418			t.Fatalf("GetVersion = %+v, %v", got, err)
419		}
420		// Enabling an unknown version fails and changes nothing.
421		if _, err := EnableVersion(dir, "nope"); !errors.Is(err, ErrUnknownVersion) {
422			t.Fatalf("got %v, want ErrUnknownVersion", err)
423		}
424		_, enabled, _ = ListVersions(dir)
425		if enabled != "strict" {
426			t.Fatalf("failed enable changed enabled version to %q", enabled)
427		}
428		// The built-in version is queryable without registration.
