622	func TestCompareVersions(t *testing.T) {
623		dir := t.TempDir()
624		// 0xza/0xzb: displacement under builtin (99 > 2*10), gone under strict (99 < 5*10... wait 5*10=50, 99>50 flagged).
625		// Use front gas 40 vs victim 10: flagged by builtin (40>20), not by strict (40<50).
626		input := `{"chainId":"1","blockHash":"0xcmp","blockNumber":7,"swaps":[` +
627			`{"TxHash":"0xfa","Pool":"p1","Trader":"w","In":1,"Out":1,"GasPrice":40,"Index":0},` +
628			`{"TxHash":"0xva","Pool":"p1","Trader":"u","In":1,"Out":1,"GasPrice":10,"Index":1},` +
629			`{"TxHash":"0xfb","Pool":"p2","Trader":"bot","In":1,"Out":1,"GasPrice":90,"Index":2},` +
630			`{"TxHash":"0xvb","Pool":"p2","Trader":"user","In":1,"Out":1,"GasPrice":10,"Index":3},` +
631			`{"TxHash":"0xbb","Pool":"p2","Trader":"bot","In":1,"Out":1,"GasPrice":80,"Index":4}]}`
632		original := replay(t, dir, input)
633		if len(original[0].Findings) != 2 {
634			t.Fatalf("setup: got %d findings, want 2", len(original[0].Findings))
