643			t.Fatalf("original version wrong: %+v", result.OriginalVersion)
644		}
645		if result.ComparedVersion.ID != "strict" || result.ComparedVersion.Rules.Displacement.Multiplier != 5 {
646			t.Fatalf("compared version wrong: %+v", result.ComparedVersion)
647		}
648		if len(result.Swaps) != 5 {
649			t.Fatalf("raw swap evidence missing: %+v", result.Swaps)
650		}
