package mevwatch

import (
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
)

func TestScratchRegisterCorruption(t *testing.T) {
	dir := t.TempDir()
	// Archive with an intact version "ok" and a corrupt version "broken"
	// (displacement.enabled missing/null variants), plus an unknown field.
	archive := `{
  "records": [],
  "versions": [
    {
      "id": "ok",
      "rules": {
        "sandwich": {"enabled": true, "severity": 3},
        "displacement": {"enabled": true, "severity": 2, "multiplier": 2}
