	// 2. Corrupt version still refused by enable/compare/replay.
	if _, err := EnableVersion(dir, "broken"); !errors.Is(err, ErrCorruptVersion) {
		t.Fatalf("enable broken: %v", err)
	}
	if _, err := Compare(dir, "1", "0xb", "broken"); !errors.Is(err, ErrCorruptVersion) {
		t.Fatalf("compare broken: %v", err)
	}
	if _, err := ReplayWithVersion(strings.NewReader(`{"chainId":"1","blockHash":"0z","blockNumber":1,"swaps":[]}`), dir, "broken"); !errors.Is(err, ErrCorruptVersion) {
		t.Fatalf("replay broken: %v", err)
	}

	// 3. Re-registering the corrupt id with valid repaired params: corruption.
	repaired := `{"id":"broken","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`
	if _, created, err := RegisterVersion(dir, []byte(repaired)); !errors.Is(err, ErrCorruptVersion) || created {
		t.Fatalf("re-register corrupt id: created=%v err=%v", created, err)
	}
	if !strings.Contains(err.Error(), "broken") || !strings.Contains(err.Error(), "enabled") {
		t.Fatalf("error must name version and field: %v", err)
	}

	// archive untouched by the refused registration
	raw2, _ := os.ReadFile(path)
	var doc2 struct {
		Versions []json.RawMessage `json:"versions"`
	}
	json.Unmarshal(raw2, &doc2)
	if !reflect.DeepEqual(doc.Versions, doc2.Versions) {
		t.Fatalf("refused registration changed versions:\n%s\n%s", doc.Versions, doc2.Versions)
	}

	// unknown-field sibling is reported corrupt too (never silently cleaned)
	unkSpec := `{"id":"unk","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`
	if _, created, err := RegisterVersion(dir, []byte(unkSpec)); !errors.Is(err, ErrCorruptVersion) || created ||
		!strings.Contains(err.Error(), "mystery") {
		t.Fatalf("re-register unknown-field id: created=%v err=%v", created, err)
	}

	// 4. Identical retry of intact "ok" -> created:false; different -> conflict.
	okSpec := `{"id":"ok","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`
	if _, created, err := RegisterVersion(dir, []byte(okSpec)); err != nil || created {
		t.Fatalf("identical retry: created=%v err=%v", created, err)
	}
	diffSpec := `{"id":"ok","rules":{"sandwich":{"enabled":true,"severity":4},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`
	if _, _, err := RegisterVersion(dir, []byte(diffSpec)); !errors.Is(err, ErrVersionConflict) {
		t.Fatalf("conflict: %v", err)
	}

	// 5. Invalid new spec rejected regardless, even with an existing id.
	if _, _, err := RegisterVersion(dir, []byte(`{"id":"ok"}`)); err == nil {
		t.Fatal("invalid spec accepted")
	}

	// 6. Invalid JSON archive -> error, no partial write.
	if err := os.WriteFile(path, []byte(`{not json`), 0o644); err != nil {
		t.Fatal(err)
	}
	if _, _, err := RegisterVersion(dir, []byte(newSpec)); err == nil {
		t.Fatal("invalid-JSON archive accepted")
	}
	if got, _ := os.ReadFile(path); string(got) != `{not json` {
		t.Fatalf("failed registration overwrote invalid archive: %s", got)
	}
}

